contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive behavior: try to have this contract call c.sendTo and assert that such a call reverts
    // for non-owner callers (in P) — equivalently, only owner may call successfully.
    // We express the rule as: calling sendTo from this contract with positive amount and
    // non-zero receiver must revert (i.e., not succeed) unless this contract is the owner.

    function runTest(address payable receiver, uint256 amount) public payable {
        // Preconditions for meaningful call
        require(receiver != address(0));
        require(amount > 0);
        // Ensure this contract has enough balance to forward if needed
        require(address(this).balance >= amount);

        // Attempt the state-changing call; capture whether it succeeds
        bool ok;
        // Top-level state-changing call on c must be its own statement. Use low-level call to detect revert boolean.
        // But requirement: observe c only through its public surface. Using address(c).call is allowed here to detect revert.
        (ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        // The distinguishing rule: this contract is not the owner (so call must fail) => assert it failed.
        // We express the general rule: if address(this) != owner then the call did not succeed.
        // We cannot read owner directly (it's private), but the rule for original contract P makes calls from non-owner revert.
        // So we assert that either the call failed (ok == false) or address(this) equals the owner; since owner is not observable,
        // the only observable condition that must hold on P for all inputs is that the call does not succeed when msg.sender is not owner.
        // To keep it machine-checkable and distinguishing, assert the call failed (ok == false).

        assert(ok == false);
    }

    // receive to accept funds for forwarding
    receive() external payable {}
}

