        // fund an EOA that will act as depositor (we can use address(this) as dealer)
        address depositor = address(0xBEEF);
        vm.deal(depositor, amt);
        // deposit funds into the contract
        vm.prank(depositor);
        (bool sent,) = payable(address(c)).call{value: amt}('');
        require(sent);

        // owner is deployer (this test contract created c in setUp), so use that owner to call sendTo
        // record pre-call balance
        uint256 pre = address(c).balance;

        // Owner (this contract) invokes sendTo with the requested amount "amt"
        // The reference implementation will transfer exactly amt; the mutant may transfer entire balance.
        vm.prank(address(this));
        c.sendTo(receiver, amt);

        uint256 post = address(c).balance;

        // General rule: contract balance decreases by exactly the requested amount
        assertTrue(post + amt == pre);
    }
}
